/**
 * Digital goods pack — Agent 17, Step 49 (Part C).
 * License-key delivery + download limits. License keys are generated by
 * the merchant's pool (imported or generated upstream); this pack only
 * allocates from a pool and enforces download counts/expiry. Keys are
 * shown to the buyer after payment — they are delivery artefacts, not
 * credentials, and are never logged in full by routes.
 */
import { z } from "zod";
import type { BusinessModulePack, PackValidation } from "./types";

export const digitalConfigSchema = z.object({
  /** Downloads allowed per purchased item. */
  maxDownloads: z.number().int().positive().default(5),
  /** Download links expire this many days after delivery. */
  linkExpiryDays: z.number().int().positive().default(30),
  /** Devices a single license may be activated on. */
  maxActivations: z.number().int().positive().default(1),
});

export type DigitalConfig = z.infer<typeof digitalConfigSchema>;

export const digitalPack: BusinessModulePack<DigitalConfig> = {
  id: "digital_goods",
  flagKey: "module.digital_goods",
  nameEn: "Digital Goods",
  nameBn: "ডিজিটাল পণ্য",
  description: "License-key delivery and download limits for digital products.",
  defaultConfig: { maxDownloads: 5, linkExpiryDays: 30, maxActivations: 1 },
  configSchema: digitalConfigSchema,
};

export type LicenseStatus = "available" | "delivered" | "revoked";

export interface LicenseKey {
  id: string;
  /** The key itself. Stored per license-pool row; delivered to the buyer once per sale. */
  key: string;
  productId: string;
  status: LicenseStatus;
  /** Order the key was delivered on, once allocated. */
  orderId: string | null;
}

export interface LicensePool {
  allocate(productId: string, orderId: string): LicenseKey | null;
  countAvailable(productId: string): number;
}

export class InMemoryLicensePool implements LicensePool {
  private keys: LicenseKey[] = [];

  addKeys(productId: string, keys: string[]): void {
    keys.forEach((key, i) => {
      this.keys.push({ id: `${productId}-key-${this.keys.length + i + 1}`, key, productId, status: "available", orderId: null });
    });
  }

  allocate(productId: string, orderId: string): LicenseKey | null {
    const found = this.keys.find((k) => k.productId === productId && k.status === "available");
    if (!found) return null;
    found.status = "delivered";
    found.orderId = orderId;
    return found;
  }

  countAvailable(productId: string): number {
    return this.keys.filter((k) => k.productId === productId && k.status === "available").length;
  }
}

export interface DownloadGrant {
  orderItemId: string;
  downloadsUsed: number;
  deliveredAt: string; // ISO
}

export type DownloadCheck =
  | { ok: true; remaining: number }
  | { ok: false; reason: "limit_reached" | "link_expired" };

export function checkDownload(config: DigitalConfig, grant: DownloadGrant, now: Date): DownloadCheck {
  const expiresAt = new Date(grant.deliveredAt).getTime() + config.linkExpiryDays * 24 * 60 * 60 * 1000;
  if (now.getTime() > expiresAt) return { ok: false, reason: "link_expired" };
  if (grant.downloadsUsed >= config.maxDownloads) return { ok: false, reason: "limit_reached" };
  return { ok: true, remaining: config.maxDownloads - grant.downloadsUsed };
}

export function validateDigitalFulfilment(pool: LicensePool, productId: string): PackValidation {
  if (pool.countAvailable(productId) <= 0) {
    return { ok: false, errors: [{ field: "licensePool", message: "No license keys available for this product." }] };
  }
  return { ok: true };
}
